def algorithm(func, dim, lb, ub, budget, rng):
    x_best = np.random.uniform(lb, ub, size=dim)
    f_best = func(x_best)

    for _ in range(budget):
        x_new = x_best + (ub - lb) * np.random.normal(size=dim)
        x_new = np.clip(x_new, lb, ub)

        if func(x_new) < f_best:
            x_best = x_new
            f_best = func(x_new)

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = rng.uniform(lb, ub, size=dim)
    best_f = func(best_x)

    for _ in range(budget):
        x = rng.uniform(lb, ub, size=dim)
        f = func(x)

        if np.any((x < lb) | (x > ub)):
            continue

        if f < best_f:
            best_x = x
            best_f = f

    return best_x
